export interface DeskFile {
  id: string;
  name: string;
  /** The draggable's `type`: what the folders' `accept` checks. */
  kind: 'image' | 'doc';
  size: string;
  /** The folder it is in. */
  place: string;
}

export interface Candidate {
  id: string;
  name: string;
  role: string;
  hue: number;
  /** The interviewers' score, out of 5. */
  score: number;
}

export interface Thing {
  id: string;
  name: string;
  icon: string;
  /** Items weigh something; a container weighs what it holds. */
  weight?: number;
  /** A bag, a pouch, a chest: it holds things. */
  container?: boolean;
  children?: Thing[];
}

/** What a thing weighs, with everything inside it. */
export const weightOf = (thing: Thing): number =>
  (thing.weight ?? 0) + (thing.children ?? []).reduce((sum, child) => sum + weightOf(child), 0);

export interface Shape {
  id: string;
  kind: 'title' | 'chart' | 'photo' | 'logo';
  label: string;
  /** Where it sits on the slide, from its top left corner, and its size: px. */
  x: number;
  y: number;
  width: number;
  height: number;
}
